def figure(pid):
    f, alt, cap, cr, u = PHOTO[pid]
    return (f'<figure class="sx-photo" id="photo-{pid}"><img src="assets/sx/{f}" alt="{esc(alt)}" loading="lazy" decoding="async" width="1000" height="666">'
            f'<figcaption>{esc(cap)} <span class="photo-credit">Credit: <a href="{u}" rel="noopener">{esc(cr)}</a></span></figcaption></figure>')

def lab3d():
    acts = [('build', '🧩', 'Build in 3D'), ('auto', '🪄', 'Auto-build'), ('explode', '💥', 'Explode / rejoin'), ('launch', '🚀', 'Launch to orbit'), ('real', '🛰️', 'Real NASA model'), ('lab', '🔄', 'Reset')]
    btn = ''.join(f'<button type="button" class="edu-bubble glass" data-tint="space" data-act="{a}"><span class="em" aria-hidden="true">{e}</span>{t}</button> ' for a, e, t in acts)
    return ('<section class="sx3d" id="sx3d" aria-labelledby="sx3d-h"><h2 id="sx3d-h">3D satellite lab</h2>'
            '<p data-level="1">Spin it, blow it apart, build it, launch it!</p>'
            '<p data-level="2">Turn the satellite in 3D, open the exploded view to see the reaction wheels hidden inside, then launch it: watch the booster drop away, the nose cone split open and the solar arrays unfold in orbit.</p>'
            '<p data-level="3">Exploded view and a full mission sequence: staging, fairing jettison, spacecraft separation, array and antenna deployment, then an optical downlink. Earth uses NASA’s Blue Marble and Black Marble maps, lit by the Sun so you can see the day and night sides.</p>'
            '<div class="sx3d-stage"><canvas role="img" aria-label="3D satellite model you can rotate, take apart, assemble and launch into orbit around Earth"></canvas><div class="sx3d-hot"></div>'
            '<p class="sx3d-fallback">The 3D lab needs WebGL. The 2D builder above and the photos below work everywhere.</p></div>'
            '<p class="sx-cap sx3d-cap" role="status" aria-live="polite"></p>'
            f'<div class="sx-ctrl">{btn}</div>'
            '<p class="sx-credit">Created by SI and Biological SI Partner</p>'
            '<p class="sx-cite">Real satellite model: Landsat 8 by NASA/Christopher R. Meaney, <a href="https://science.nasa.gov/3d-resources/landsat-8/" rel="noopener">NASA 3D Resources</a>. Earth maps: <a href="https://visibleearth.nasa.gov/images/73909/december-blue-marble-next-generation-w-topography-and-bathymetry" rel="noopener">NASA Blue Marble</a> and <a href="https://visibleearth.nasa.gov/images/79765/night-lights-2012-map" rel="noopener">NASA Black Marble</a>. Credit: NASA.</p></section>')

def nasa_plus(stage):
    cards = ''.join(f'<li><a class="sx-np" href="{u}" rel="noopener" target="_blank"><span class="sx-np-k">Watch it for real on NASA+</span><b>{esc(t)}</b><span>{esc(b)}</span></a></li>' for st, t, u, b in NASA_PLUS if st == stage)
    return f'<ul class="sx-nplus">{cards}</ul>'

def live_strip():
    return ('<aside class="sx-live" aria-label="Next live launch"><span class="em" aria-hidden="true">🔴</span><span>Next live launch: watch it free on NASA+.</span> '
            '<a href="https://www.nasa.gov/live/" rel="noopener" target="_blank">NASA live streams</a> · <a href="Project-Rawane.html#launches">Our live launch tracker</a></aside>')

def videos():
    out = ''
    for stem, t, cr, u in VIDEOS:
        out += (f'<figure class="sx-vid"><video controls playsinline preload="none" poster="assets/sx/{stem}.jpg" aria-label="{esc(t)}"><source src="assets/sx/{stem}.mp4" type="video/mp4">'
                f'<track kind="captions" src="assets/sx/{stem}.en.vtt" srclang="en" label="English" default></video>'
                f'<figcaption>{esc(t)} <span class="photo-credit">Credit: <a href="{u}" rel="noopener">{esc(cr)}</a></span></figcaption></figure>')
    return ('<section class="sx-deep" id="sx-real"><h2>Real hardware, real launches</h2>'
            '<p>These clips come from NASA. Captions are on; tap CC to change them.</p>'
            f'<div class="sx-vids">{out}</div>' + nasa_plus('Build') + '</section>')

